    ur: "\u06A9\u0648\u0632\u06CC\u06A9\u0648\u0688\u060C \u06A9\u06CC\u0631\u0627\u0644\u06C1\u060C \u0627\u0646\u0688\u06CC\u0627",
    hi: "\u0915\u094B\u091D\u093F\u0915\u094B\u0921, \u0915\u0947\u0930\u0932, \u092D\u093E\u0930\u0924",
