        suggestions = ["\u0D39\u0D3F\u0D28\u0D4D\u0D26\u0D41 \u2014 \u0D08\u0D34\u0D35 (OBC)", "\u0D07\u0D38\u0D4D\u0D32\u0D3E\u0D02 \u2014 \u0D2E\u0D3E\u0D2A\u0D4D\u0D2A\u0D3F\u0D33 (OBC)", "\u0D39\u0D3F\u0D28\u0D4D\u0D26\u0D41 \u2014 \u0D2A\u0D41\u0D32\u0D2F (SC)", "\u0D15\u0D4D\u0D30\u0D3F\u0D38\u0D4D\u0D24\u0D4D\u0D2F\u0D7B \u2014 \u0D32\u0D24\u0D4D\u0D24\u0D40\u0D7B (OBC)", "\u0D39\u0D3F\u0D28\u0D4D\u0D26\u0D41 \u2014 \u0D35\u0D3F\u0D36\u0D4D\u0D35\u0D15\u0D7C\u0D2E\u0D4D\u0D2E"];
