function createPresetEntry(id, badgeIcon, badgeMalayalam, titleMalayalam, subtitleMalayalam, dataObj) {
  const normalizedData = {
    ...dataObj,
    presetId: id,
    modelPresetId: id,
    showTotalAndPercentage: dataObj.showTotalAndPercentage !== void 0 ? dataObj.showTotalAndPercentage : dataObj.showTotalAndPercent,
    showSummaryCards: dataObj.showSummaryCards !== void 0 ? dataObj.showSummaryCards : dataObj.showSummaryBox,
    showHeadmasterSignature: dataObj.showHeadmasterSignature !== void 0 ? dataObj.showHeadmasterSignature : dataObj.showHeadmasterSign
  };
  return {
    id,
    badgeIcon,
    badgeMalayalam,
    titleMalayalam,
    subtitleMalayalam,
    data: normalizedData,
    buildData: () => JSON.parse(JSON.stringify(normalizedData))
  };
}
