function convertGovFormToLetterData(form) {
  const todayMl = (/* @__PURE__ */ new Date()).toLocaleDateString("ml-IN");
  const genericOffice = form.recipientOffice.replace(/,\s*തിരുവനന്തപുരം/g, "").trim();
  return {
    documentHeading: form.titleMalayalam,
    formCode: form.formCode,
    portalName: form.portalName,
    portalUrl: form.portalUrl,
    senderName: "",
    senderAddress: "",
    senderPhone: "",
    recipientTitle: form.recipientTitle,
    recipientOffice: genericOffice,
    recipientPlace: "\u0D15\u0D47\u0D30\u0D33\u0D02.",
    subject: form.subject,
    reference: "",
    salutation: "\u0D38\u0D7C / \u0D2E\u0D3E\u0D21\u0D02,",
    bodyParagraphs: [...form.bodyParagraphs],
    closingPhrase: "\u0D35\u0D3F\u0D36\u0D4D\u0D35\u0D38\u0D4D\u0D24\u0D24\u0D2F\u0D4B\u0D1F\u0D46,",
    place: "",
    date: todayMl,
    enclosures: [...form.enclosures],
    structuredFields: form.structuredFields.map((f) => {
      const sampleVal = (f.value || "").trim();
      return {
        ...f,
        // Never pre-fill a stranger's personal name, Aadhaar, Ration card, or income as the live value;
        // provide it as a clean placeholder hint so unedited fields remain empty until filled by the user.
        value: "",
        placeholder: sampleVal ? `\u0D09\u0D26\u0D3E: ${sampleVal}` : f.placeholder || "\u0D07\u0D35\u0D3F\u0D1F\u0D46 \u0D2A\u0D42\u0D30\u0D3F\u0D2A\u0D4D\u0D2A\u0D3F\u0D15\u0D4D\u0D15\u0D41\u0D15..."
      };
    })
  };
}
function normalizeMixedGovQuery(raw) {
  if (!raw) return "";
  let s = raw.normalize("NFC").toLowerCase().trim();
  s = s.replace(/സർട്ടിഫ[a-z]+/gi, "\u0D38\u0D7C\u0D1F\u0D4D\u0D1F\u0D3F\u0D2B\u0D3F\u0D15\u0D4D\u0D15\u0D31\u0D4D\u0D31\u0D4D certificate").replace(/സെർട്ടിഫ[a-z\u0D00-\u0D7F]*/gi, "\u0D38\u0D7C\u0D1F\u0D4D\u0D1F\u0D3F\u0D2B\u0D3F\u0D15\u0D4D\u0D15\u0D31\u0D4D\u0D31\u0D4D certificate").replace(/സർട്ടിഫിക്കറ്റ്|സർട്ടിഫിക്കറ്|സർട്ടിഫികറ്റ്/g, "\u0D38\u0D7C\u0D1F\u0D4D\u0D1F\u0D3F\u0D2B\u0D3F\u0D15\u0D4D\u0D15\u0D31\u0D4D\u0D31\u0D4D certificate").replace(/\b(varumanam|varumana)\b/gi, "\u0D35\u0D30\u0D41\u0D2E\u0D3E\u0D28 income").replace(/\b(jathi|jaathi|caste)\b/gi, "\u0D1C\u0D3E\u0D24\u0D3F caste").replace(/\b(nativity|residence|sthirathamasam)\b/gi, "\u0D28\u0D47\u0D31\u0D4D\u0D31\u0D3F\u0D35\u0D3F\u0D31\u0D4D\u0D31\u0D3F \u0D38\u0D4D\u0D25\u0D3F\u0D30\u0D24\u0D3E\u0D2E\u0D38 nativity").replace(/\b(pokkuvaravu|possession|kaivasavakasam)\b/gi, "\u0D2A\u0D4B\u0D15\u0D4D\u0D15\u0D41\u0D35\u0D30\u0D35\u0D4D \u0D15\u0D48\u0D35\u0D36\u0D3E\u0D35\u0D15\u0D3E\u0D36 possession").replace(/\b(anantharavakasam|legal\s*heir|heirship)\b/gi, "\u0D05\u0D28\u0D28\u0D4D\u0D24\u0D30\u0D3E\u0D35\u0D15\u0D3E\u0D36 \u0D32\u0D40\u0D17\u0D7D \u0D39\u0D46\u0D2F\u0D7C legal heir").replace(/\b(ration\s*card|ration)\b/gi, "\u0D31\u0D47\u0D37\u0D7B \u0D15\u0D3E\u0D7C\u0D21\u0D4D ration").replace(/\b(pension|vardhakya|vidhava)\b/gi, "\u0D2A\u0D46\u0D7B\u0D37\u0D7B \u0D35\u0D3E\u0D7C\u0D26\u0D4D\u0D27\u0D15\u0D4D\u0D2F\u0D15\u0D3E\u0D32 \u0D35\u0D3F\u0D27\u0D35\u0D3E pension").replace(/\b(birth|janana)\b/gi, "\u0D1C\u0D28\u0D28 birth").replace(/\b(death|marana)\b/gi, "\u0D2E\u0D30\u0D23 death").replace(/\b(marriage|vivaha|vivaham)\b/gi, "\u0D35\u0D3F\u0D35\u0D3E\u0D39 marriage").replace(/\b(kseb|electricity|current\s*bill|vaidyuthi)\b/gi, "\u0D15\u0D46.\u0D0E\u0D38\u0D4D.\u0D07.\u0D2C\u0D3F \u0D35\u0D48\u0D26\u0D4D\u0D2F\u0D41\u0D24\u0D3F kseb").replace(/\b(kwa|water\s*authority|kudivellam)\b/gi, "\u0D35\u0D3E\u0D1F\u0D4D\u0D1F\u0D7C \u0D05\u0D24\u0D4B\u0D31\u0D3F\u0D31\u0D4D\u0D31\u0D3F \u0D15\u0D41\u0D1F\u0D3F\u0D35\u0D46\u0D33\u0D4D\u0D33 kwa").replace(/\b(driving\s*licen[cs]e|learners|rto|mvd)\b/gi, "\u0D21\u0D4D\u0D30\u0D48\u0D35\u0D3F\u0D02\u0D17\u0D4D \u0D32\u0D48\u0D38\u0D7B\u0D38\u0D4D mvd rto").replace(/\b(rajikkathu|raji|resign|resignation)\b/gi, "\u0D30\u0D3E\u0D1C\u0D3F\u0D15\u0D4D\u0D15\u0D24\u0D4D\u0D24\u0D4D \u0D30\u0D3E\u0D1C\u0D3F resignation").replace(/\b(apeksha|application)\b/gi, "\u0D05\u0D2A\u0D47\u0D15\u0D4D\u0D37 application");
  return s;
}
