    ...localConverted,
    fullName: targetLang === "en" ? fullName.toUpperCase() : fullName,
    jobTitle: targetLang === "en" ? jobTitle.toUpperCase() : jobTitle,
    currentLocation,
    visaStatus,
    drivingLicense,
    maritalStatus,
    professionalSummary,
    declaration,
    cvPlace,
    signatureName: targetLang === "en" ? signatureName.toUpperCase() : signatureName,
    languages,
    coreSkills,
    workExperience,
    education
